describe('WCAG 2.1 AA Colour Contrast Compliance', () => {
  beforeEach(() => {
    cy.visit('/accessibility-checker');
  });

  it('should pass colour contrast for WCAG 2.1 AA standards', () => {
    // Intercept the API call to get colour contrast data
    cy.intercept('GET', '/api/contrast-checker', {
      statusCode: 200,
      body: {
        success: true,
        message: 'Contrast check passed',
        details: {
          foreground: '#FFFFFF',
          background: '#000000',
          contrastRatio: '4.51:1',
          pass: true
        }
      }
    }).as('contrastCheck');

    // Verify the contrast check button is visible
    cy.get('[data-testid="contrast-check-button"]').should('be.visible');

    // Click the contrast check button
    cy.get('[data-testid="contrast-check-button"]').click();

    // Wait for the API response
    cy.wait('@contrastCheck');

    // Verify success message is displayed
    cy.get('[data-testid="success-message"]').should('be.visible');
    cy.get('[data-testid="success-message"]').should('contain', 'Contrast check passed');

    // Verify contrast ratio is displayed
    cy.get('[data-testid="contrast-ratio"]').should('be.visible');
    cy.get('[data-testid="contrast-ratio"]').should('contain', '4.51:1');

    // Verify pass/fail badge is displayed
    cy.get('[data-testid="pass-fail-badge"]').should('be.visible');
    cy.get('[data-testid="pass-fail-badge"]').should('contain', 'Pass');

    // Verify contrast ratio meets WCAG 2.1 AA standards
    cy.get('[data-testid="contrast-ratio"]').should('have.value', '4.51:1');
    cy.get('[data-testid="contrast-ratio"]').should('be.greaterThanOrEqual', '4.5:1');
  });

  it('should fail colour contrast and display appropriate error message', () => {
    // Intercept the API call with a failing contrast ratio
    cy.intercept('GET', '/api/contrast-checker', {
      statusCode: 200,
      body: {
        success: false,
        message: 'Contrast check failed',
        details: {
          foreground: '#FFFFFF',
          background: '#CCCCCC',
          contrastRatio: '2.12:1',
          pass: false
        }
      }
    }).as('contrastCheckFail');

    // Verify the contrast check button is visible
    cy.get('[data-testid="contrast-check-button"]').should('be.visible');

    // Click the contrast check button
    cy.get('[data-testid="contrast-check-button"]').click();

    // Wait for the failed API response
    cy.wait('@contrastCheckFail');

    // Verify error message is displayed
    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'Contrast check failed');

    // Verify contrast ratio is displayed
    cy.get('[data-testid="contrast-ratio"]').should('be.visible');
    cy.get('[data-testid="contrast-ratio"]').should('contain', '2.12:1');

    // Verify pass/fail badge is displayed with failure
    cy.get('[data-testid="pass-fail-badge"]').should('be.visible');
    cy.get('[data-testid="pass-fail-badge"]').should('contain', 'Fail');

    // Verify contrast ratio does not meet WCAG 2.1 AA standards
    cy.get('[data-testid="contrast-ratio"]').should('have.value', '2.12:1');
    cy.get('[data-testid="contrast-ratio"]').should('be.lessThanOrEqual', '4.5:1');
  });
});
